package com.aac.ieojwo.routine.controller;import com.aac.ieojwo.common.api.ApiResponse;import com.aac.ieojwo.routine.service.RoutineService;import com.aac.ieojwo.routine.service.RoutineService.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.core.oidc.user.OidcUser;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/me/aac-users/{userId}/routines")public class RoutineController{private final RoutineService service;public RoutineController(RoutineService s){service=s;}@GetMapping public ApiResponse<List<RoutineResponse>> list(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId){return ApiResponse.ok(service.list(p,userId));}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ApiResponse<RoutineResponse> create(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@RequestBody RoutineRequest r){return ApiResponse.ok(service.save(p,userId,null,r));}@PutMapping("/{routineId}")public ApiResponse<RoutineResponse> update(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@PathVariable Long routineId,@RequestBody RoutineRequest r){return ApiResponse.ok(service.save(p,userId,routineId,r));}@DeleteMapping("/{routineId}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@PathVariable Long routineId){service.delete(p,userId,routineId);}}
